names = ('utf-' + str(width), 'UTF' + str(width), ' utf---' + str(width) + ' ')
policies = ('strict',)
texts = ('', 'A', 'é', 'Ā', '🐍', '\ufeffA', '\ufffe', '\ud800', '\udfff', '\ud800A\udfffZ')
